const table = (note: string, rows: ArticlePriceTable["rows"]): ArticlePriceTable => ({asOf,note,rows});

export const costArticles: Article[] = [
  a({slug:"new-zealand-travel-cost-2026",title:"NZ Travel Cost 2026: Daily Budget for Campers (NZD)",description:"What a day in New Zealand costs in 2026: NZ$75 to $120 per person for a lean camper, $150 to $260 for a comfortable trip, with dated prices.",category:"Costs & budget",region:"New Zealand",places:["Auckland","Rotorua","Queenstown","West Coast","Fiordland"],imageAlt:"Traveller calculating a New Zealand road trip budget",intro:"A day in New Zealand costs about NZ$75 to $120 per person for a lean camper or backpacker, $150 to $260 for a comfortable independent trip and $280 to $450 with private rooms and paid activities, before vehicle hire and flights. The route and pace matter more than a national average: moving daily raises fuel and booking pressure, while slower travel makes self-catering and weekly rates easier to use.",priceTable:table("Planning scenarios for one traveller. Vehicle rental, long-distance transport and international flights are excluded because dates and party size change them sharply.",[{label:"Lean camper or backpacker",nzdLow:75,nzdHigh:120,unit:"per person per day"},{label:"Comfortable independent trip",nzdLow:150,nzdHigh:260,unit:"per person per day"},{label:"Private rooms and paid activities",nzdLow:280,nzdHigh:450,unit:"per person per day"}]),sections:[s("Build from the travel style","A lean daily figure assumes groceries, shared or simple accommodation and careful local transport. It does not support a private room, restaurant dinner and major activity every day.","For a campervan pair, calculate the vehicle once for the group, then add fuel, camps and food. Dividing every line per person can hide the large fixed costs."),s("Location and season","Queenstown, Aoraki, summer beaches and event dates can sit far above an ordinary town. Remote areas also add fuel and grocery freight costs.","Price the hard dates directly, then use the national ranges for the flexible days between them."),s("Keep a usable reserve","Hold money for a changed ferry, extra accommodation night, tyre or medical need. A legal campsite backup belongs in the budget even when freedom camping is planned.","Review actual spending every few days. Fuel, takeaway food and activities are the lines most likely to drift quietly." ),s("What a lean day actually looks like","A lean day means cooking almost every meal, mixing free and low-cost DOC sites, and treating paid activities as occasional rather than daily. It is genuinely achievable for months at a time, and thousands of people do it, but it requires a vehicle set up for self-sufficiency and a tolerance for basic facilities.","Where it breaks down is the assumption that lean means free. Showers, laundry, water, dump stations and the occasional serviced night all cost something, and a budget that has no line for them will be wrong by the end of the first week."),s("The two islands cost differently","The South Island generally involves longer distances between towns, more expensive fuel outside the main centres, and higher accommodation pressure in Queenstown, Wānaka and Aoraki. The North Island packs more into shorter drives, which lowers fuel but raises the number of paid attractions within easy reach.","If the budget is tight, a slower North Island trip usually costs less per day than the equivalent South Island route. If the budget is fixed and the time is short, the South Island rewards the spend more visibly."),s("Costs that only appear once you are here","The Cook Strait crossing, the insurance excess reduction on a rental, one-way vehicle fees, a SIM or roaming plan, and the deposit held on your card are all real amounts that rarely appear in a daily budget. Together they routinely add several hundred dollars to a fortnight.","Activities are the other quiet line. A single glacier flight, jet boat or Milford cruise can equal several days of ordinary travel, so decide in advance which two or three are worth it rather than deciding in the moment at each one.",["Price the ferry separately","Excess reduction is a real cost","Pick your big activities in advance"]),s("Where the money actually goes","For most camping trips the order is vehicle, fuel, food, campsites, activities. Campsites are usually a smaller line than people expect, and fuel a larger one, which is why choosing a slower route saves more than choosing cheaper sites.","That ordering also tells you where to look when the budget is drifting. Cutting a $25 campsite to $0 saves less than removing one 300 kilometre detour, and it costs you a shower."),{heading:"Paying for things while you are here",body:["Contactless card payment is accepted almost everywhere including small rural cafes, and cash is genuinely rare. Many venues add a card surcharge, typically one to two percent, which appears at the till rather than on the menu.","Foreign transaction fees are the quiet cost. A travel card or a bank that does not charge them saves a meaningful amount over a month, and it removes the temptation to accept dynamic currency conversion at the terminal, which is always a worse rate. Heading to Australia too? The AussieCamps guide to travel costs in Australia does the same sums there.","Keep a small amount of cash for honesty boxes at DOC campsites, roadside produce stalls and the occasional rural shop with an unreliable connection. Fifty dollars in notes covers most of what cash is still needed for."]}],sources:[numbeo,{label:"Stats NZ June 2026 CPI",url:"https://www.stats.govt.nz/information-releases/consumers-price-index-june-2026-quarter/"},rbnz]}),
  a({slug:"new-zealand-grocery-prices-2026",title:"NZ Grocery Prices 2026: Milk, Eggs, Bread, Meat",description:"Stats NZ average supermarket prices for September 2026: milk, bread, eggs, chicken, mince and produce, plus a NZ$116 weekly basket, in ten currencies.",category:"Costs & budget",region:"New Zealand supermarkets",places:["Auckland","Wellington","Christchurch","Regional towns","Remote shops"],imageAlt:"Fresh groceries in a New Zealand supermarket",intro:"In New Zealand a litre of milk costs about NZ$2.53, a 600 g loaf of white bread $2.39 and a dozen eggs $8.37 at Stats NZ's national average prices for September 2026, and a basic week of groceries for one person comes to about NZ$116. Self-catering is the most direct way to control a camping budget, but these are averages, not a promise for every shelf or week.",priceTable:{asOf:"2026-10-16",note:"Stats NZ national average retail prices for September 2026, released on 16 October 2026. Milk is per litre from the 2-litre average. Specials, brand, pack size, season and remote freight move any one shelf above or below these averages.",rows:[{label:"Milk, standard",nzdLow:2.53,unit:"1 litre"},{label:"White bread, sliced",nzdLow:2.39,unit:"600 g loaf"},{label:"Eggs",nzdLow:8.37,unit:"dozen"},{label:"Chicken breast",nzdLow:15.21,unit:"1 kg"},{label:"Beef mince",nzdLow:24.77,unit:"1 kg"},{label:"Apples",nzdLow:4.2,unit:"1 kg"},{label:"Tomatoes",nzdLow:10.19,unit:"1 kg"},{label:"Potatoes",nzdLow:3.27,unit:"1 kg"}]},sections:[s("Shop before the remote leg","Major supermarkets bring range and competition, while small isolated stores pay for freight and carry less stock. Buy durable basics before East Cape, Fiordland or long West Coast sections.","Support local shops for fresh needs without expecting a city discount. Their value includes being open where another option is hours away."),s("Cook from overlapping ingredients","Plan meals that reuse rice, pasta, vegetables, eggs and one or two proteins. A compact fridge rewards short ingredient lists and disciplined leftovers.","Watch unit prices rather than the pack headline. Large packs save money only when storage and refrigeration prevent waste."),s("Food prices move","Stats NZ reported food prices up 2.4 percent in the year to September 2026, led by grocery food, up 3.0 percent, and meat, poultry and fish, up 3.2 percent, while fruit and vegetables fell 1.8 percent. Onions rose more than 86 percent, the biggest annual rise since that series began in 2008.","Use the range for planning, then record the first real shop and update the remainder of the budget." ),s("The two big chains and the cheaper options","Woolworths, formerly Countdown, and New World cover most of the country, with Pak'nSave generally the cheapest of the large-format stores where one is available. Prices differ noticeably between banners in the same town, so it is worth a short detour to the cheaper one when you are doing a full restock rather than topping up.","Farmers markets and roadside stalls are excellent for produce and frequently cheaper than a supermarket for what is in season locally. They are also usually cash and morning-only, which is worth knowing before you plan around them.",["Pak'nSave for the big shop","Roadside stalls for seasonal produce","Markets are cash and mornings"]),s("Why remote shops cost more","A small store on the West Coast, in the far north or on the East Cape carries freight costs, lower turnover and less competition. Expect meaningful premiums on staples and a narrower range of sizes, particularly for fresh produce and dairy.","This is not price gouging so much as arithmetic, and those shops are often the only reason a small community has a shop at all. Restock properly in the last large centre, then buy locally for the things worth buying locally."),s("Shopping for a small fridge","Campervan fridges are small, and the ones running off the vehicle battery lose efficiency in heat. Buy for two or three days rather than a week, favour ingredients that work in several meals, and keep raw meat sealed and at the bottom where it cannot drip.","Tinned fish, eggs, hard cheese, oats, rice, pasta and root vegetables all survive without much refrigeration and cover a lot of meals. That base means one bad ice day does not cost you the whole shop.",["Shop for three days, not seven","Ingredients that work in several meals","Seal and store raw meat low"]),s("A realistic weekly figure","Priced at Stats NZ's September 2026 averages, a basic week for one person cooking most meals comes to about NZ$116: four litres of milk, two loaves, a dozen eggs, a kilo of chicken breast, half a kilo of mince, cheese, butter, yoghurt, rice, pasta and sauce, instant coffee, and fruit and vegetables. Couples spend less per person on shared staples, while premium meat, convenience food, dietary needs and remote stores push it up quickly.","Keep coffee, takeaway and shared meals in a separate line. Calling every food purchase groceries hides the spending that is easiest to adjust when the budget needs correcting."),{heading:"Seasonal produce and what is worth buying",body:["Buying what is in season locally is where the real saving sits. Stone fruit in Central Otago in January and February, berries in the Bay of Plenty over summer, avocados in Northland, and apples in Hawke's Bay in autumn are all dramatically cheaper at the source.","Roadside stalls in growing regions frequently run on an honesty box and undercut supermarkets substantially. Carry small notes and a bag, because these are usually cash-only and appear without warning.","Out-of-season fresh produce is imported and priced accordingly. Building meals around whatever is cheap that week rather than a fixed shopping list is the single habit that most reduces a long-trip food bill. Shopping across the Tasman as well? The AussieCamps guide to grocery prices in Australia has the prices there."]}],sources:[{label:"Stats NZ selected price indexes, September 2026",url:"https://www.stats.govt.nz/information-releases/selected-price-indexes-september-2026/"},{label:"Stats NZ: food prices up 2.4 percent in the year to September 2026",url:"https://www.stats.govt.nz/information-releases/selected-price-indexes-september-2026/"},rbnz]}),
  a({slug:"eating-out-new-zealand-prices-2026",title:"Eating Out in NZ: 2026 Meal and Coffee Prices",description:"What eating out costs in New Zealand in 2026: a cappuccino $5 to $7.50, a cheap meal $18 to $50, dinner for two $100 to $200, and how to budget it.",category:"Costs & budget",region:"New Zealand towns and cities",places:["Auckland","Wellington","Christchurch","Queenstown","Regional cafes"],imageAlt:"Cafe meal and coffee in New Zealand",intro:"Eating out ranges from a bakery lunch to a three-course city dinner. The national figures provide useful scale, while exact venues and resort towns can sit outside them.",priceTable:table("Community-contributed New Zealand ranges updated June 2026. Tips are not generally compulsory, but card surcharges and holiday pricing may apply.",[{label:"Inexpensive restaurant meal",nzdLow:18,nzdHigh:50,unit:"one person"},{label:"Fast-food combo",nzdLow:15,nzdHigh:20,unit:"one meal"},{label:"Mid-range dinner",nzdLow:100,nzdHigh:200,unit:"two people, three courses"},{label:"Cappuccino",nzdLow:5,nzdHigh:7.5,unit:"one cup"},{label:"Soft drink",nzdLow:3,nzdHigh:5.29,unit:"330 ml"}]),sections:[s("Choose which meal matters","Buy breakfast ingredients and road lunches, then spend deliberately on one local dinner. This keeps convenience food from becoming an unplanned three-times-daily cost.","Bakeries, food courts and takeaway counters can provide a middle option, but compare portion and nutrition rather than price alone."),s("Location changes the bill","Waterfronts, ski towns and isolated attractions can charge more than suburban centres. The premium may still be worthwhile when it removes parking or another drive.","Check menus before sitting down when the budget is tight. Public holiday surcharges can apply and should be shown."),s("Record the full outing","Add drinks, transport, parking and any card surcharge to the meal. A nominally cheap restaurant across town can cost more than walking to a slightly dearer one.","Keep restaurant spending separate from groceries so the source of a budget overrun remains visible." ),s("Where the price actually sits","A bakery pie and a coffee is a genuinely cheap lunch and available in almost every town. A cafe brunch is the most common mid-range spend and adds up faster than people expect. A restaurant dinner with drinks is frequently the largest single line in a day, ahead of accommodation.","Fish and chips remains the best value hot meal in most coastal towns, and the quality is usually better in the smaller ones. Ordering at the counter and eating outside costs a fraction of table service for a comparable meal."),s("Surcharges and payment fees","Public holiday surcharges are legal and common, typically 10 to 15 percent, and must be disclosed. Card surcharges also appear at many venues, particularly for credit cards and contactless payments, and they are applied at the till rather than shown on the menu.","Tipping is not expected in New Zealand and no one will think less of you for not doing it. Some venues now present a tipping prompt on the payment terminal, which is a recent import rather than a local norm.",["Holiday surcharges are normal","Card fees appear at the till","Tipping is not expected"]),s("Eating well in a tourist town","Queenstown, Wānaka, Taupō and Paihia all carry a visitor premium, and the restaurants directly on the waterfront are usually the most expensive and rarely the best. Walking two streets back typically finds better food at a lower price.","Lunch menus at good restaurants often deliver most of the dinner experience for considerably less. If you want one memorable meal in an expensive town, book it at lunchtime."),s("Deciding where eating out earns its place","Spend deliberately on meals tied to the place: crayfish in Kaikōura, whitebait on the West Coast in season, Bluff oysters in the south, a Hawke's Bay winery lunch. These are things you cannot cook in a van and will remember.","Use simple groceries on transfer days, when you are arriving late and leaving early and the meal is fuel rather than an experience. That pattern buys you the good meals without making every day expensive.",["Spend on food tied to the region","Groceries on transfer days","Lunch menus beat dinner prices"]),{heading:"Bakeries, and the mince and cheese question",body:["The bakery pie is the cheapest hot meal in the country and a genuine part of the culture, with an annual national competition taken more seriously than an outsider would expect. Small-town bakeries frequently beat city ones.","Fish and chips ordered at the counter and eaten outside is the other reliable cheap meal, and quality is usually higher in coastal towns than in cities. Ask what the fish of the day is rather than ordering generically.","Cafes generally stop serving food earlier than visitors expect, often mid-afternoon, and small towns can have nothing open after 8pm. Carrying something you can cook is what stops a late arrival becoming an expensive or missed dinner. If Australia is on the list as well, the AussieCamps guide to eating out in Australia covers meal prices there."]}],sources:[numbeo,rbnz]}),
  a({slug:"beer-wine-coffee-prices-new-zealand",title:"How Much Is a Beer in New Zealand? Pub, Supermarket and Bottle Store Prices (2027)",description:"A pint or handle costs about NZ$10 to $16 in a New Zealand pub and a supermarket dozen $24 to $34. Prices town by town, where to buy, happy hours, wine and coffee.",category:"Costs & budget",region:"New Zealand",places:["Pubs","Supermarkets","Bottle stores","Cafes","Cellar doors"],imageAlt:"New Zealand coffee and wine on a table",related:["eating-out-new-zealand-prices-2026","new-zealand-grocery-prices-2026","cigarette-prices-new-zealand","alcohol-fatigue-driving-new-zealand","hawkes-bay-wairarapa-wine-trail-campervan","new-zealand-travel-cost-2026"],intro:"A beer in a New Zealand pub costs about NZ$10 to $16 for a pint or handle of local lager or craft, a little less in a country pub and a little more in Queenstown. From a supermarket or bottle store a six-pack is about $14 to $25 and a dozen of the big brands $24 to $34, so a cold one at camp costs a fraction of a round at the bar. Supermarkets sell beer and wine but not spirits, and prices creep up every year, so treat these as today's ranges.",priceTable:{asOf:"2026-11-16",note:"Typical ranges in November 2026. Pub prices vary with the town, the venue and the brand, shop prices drop a long way on special, and all of them rise a little each year.",rows:[{label:"Cappuccino",nzdLow:5,nzdHigh:7.5,unit:"cafe"},{label:"Local beer on tap",nzdLow:10,nzdHigh:16,unit:"pint or handle in a pub"},{label:"Imported beer",nzdLow:10,nzdHigh:15,unit:"330 ml bottle in a bar"},{label:"Local beer from a shop",nzdLow:3,nzdHigh:7,unit:"500 ml can or bottle"},{label:"Mid-range wine",nzdLow:12,nzdHigh:25,unit:"750 ml bottle from a shop"}]},sections:[{heading:"Beer prices town by town",body:["The table gives today's usual range for a pint or handle of local beer on tap, and for a six-pack and a dozen of 330 ml bottles or cans from a supermarket or bottle store. The pub column runs from a mainstream lager at the low end to a craft pint at the top. The shop columns run from the big national brands to local craft, and the low end is usually a supermarket special.","Shop prices hardly change from town to town, because the supermarket chains price the same nationwide, so the real difference is in the pub. Queenstown and the centres of Auckland and Wellington sit at the top, while student Dunedin and country pubs sit at the bottom. In a remote town the only shop may be a small grocery or a bottle store, where a dozen costs a few dollars more."],table:{caption:"Typical beer prices in New Zealand, November 2026 (NZ$)",head:["Town","Pub pint or handle","Six-pack from a shop","Dozen from a shop"],rows:[["Auckland","$11 to $16","$14 to $25","$24 to $34"],["Wellington","$11 to $17","$14 to $25","$24 to $34"],["Christchurch","$10 to $15","$14 to $24","$24 to $33"],["Queenstown","$12 to $18","$16 to $26","$26 to $36"],["Rotorua","$10 to $14","$14 to $24","$24 to $33"],["Dunedin","$9 to $14","$14 to $24","$24 to $33"],["Nelson","$10 to $15","$14 to $25","$24 to $34"],["Small-town pubs","$9 to $13","$16 to $27","$26 to $36"]]}},s("Pints, handles and jugs in the pub","Ask for a pint or a handle and you get a glass of about 425 to 500 ml, not always the full 568 ml pint you may know from home; a handle is the same pour in a glass with a handle. Expect about $10 to $16 for a mainstream lager or a local craft beer, a little more for a strong hazy IPA, and $10 to $15 for a 330 ml imported bottle.","A jug of about 1.1 litres, usually $20 to $32, is the classic way for a group to share and works out cheaper per glass. Craft bars and brewery taprooms often pour smaller glasses of around 300 ml, and a tasting paddle of four or five small pours costs about $15 to $25, which is a good way to try the local beers without buying full pints."),s("Supermarkets sell beer and wine, but not spirits","Woolworths, New World, Pak'nSave and most Four Square stores sell beer, cider and wine, and they are usually the cheapest place to buy them. They cannot sell spirits or the spirit-based premixed drinks Kiwis call RTDs, so for a bottle of gin or rum, or a box of bourbon and cola, you need a bottle store such as Liquorland, Super Liquor, Liquor King or The Bottle-O.","Beer comes in six-packs, dozens and bigger packs of 15, 18 or 24, and the bigger the pack, the cheaper each can. Supermarkets run beer and wine specials most weeks, so the same dozen can cost $24 one week and $32 the next. Bottle stores often match the supermarket on the big brands and carry more craft beer, cold beer and spirits."),s("Coffee: a flat white a day adds up","New Zealand takes coffee seriously, and even a small-town cafe usually makes a very good flat white. A flat white or cappuccino costs about $5 to $7.50, with city and Queenstown cafes at the top, and plant milk or an extra shot adds 50 cents to a dollar. Two cups a day for two people comes to $150 or more a week, and it never feels like a decision.","A stovetop pot or plunger in the van covers the morning cup for a fraction of the cost and leaves the cafe stop as a treat rather than a habit. Supermarket ground coffee is good, and most travellers who do this end up enjoying the cafe coffee more, not less.",["Two cups a day adds up fast","Make the morning cup yourself","Small-town coffee is often excellent"]),s("Wine: supermarket bottles and cellar doors","Wine is where New Zealand is good value. A decent bottle of local Sauvignon Blanc, Pinot Gris or Pinot Noir costs about $12 to $25 at the supermarket, often less on special, and a glass in a bar or restaurant is about $11 to $18. Buy the region's wine in the region: Marlborough for Sauvignon Blanc, Central Otago for Pinot Noir and Hawke's Bay for reds.","Cellar doors often charge $10 to $25 for a tasting, and many take it off the price if you buy a bottle. Buying at the vineyard is rarely cheaper than the supermarket, but it is the only way to get the small-batch wines that never reach a shelf. Sort out a driver or a tour before a tasting afternoon, not after it."),s("Drinking and the driving day","New Zealand's adult limit is 250 micrograms per litre of breath or 50 milligrams per 100 millilitres of blood, and it is zero for drivers under twenty. Police run checkpoints often, including on rural roads and in the middle of the day.","The only safe plan on a road trip is to keep drinking and driving apart: stay where you drink, have a sober driver, or open a beer once the van is parked for the night. Fatigue and alcohol add up, and a limit is never an allowance.",["Zero limit under 20","Checkpoints are common on rural roads","Park for the night before drinking"]),s("The cheapest ways to drink","Happy hour is common in pubs and bars, often somewhere between 4pm and 7pm, with pints at about $8 to $10, and some pubs run cheap jug nights or a meal with a pint. Offers are low-key, because the law limits drinks deals that push heavy drinking, so ask at the bar or check the board rather than looking for big signs.","The biggest saving is drinking at camp: a supermarket dozen on special works out at about $2 to $3 a can, against $10 or more for a glass in the pub. Buy the bigger pack, watch the weekly specials, bring your duty-free allowance of 4.5 litres of beer or wine and three bottles of spirits when you fly in, and keep the beer cold in a chilly bin rather than paying extra for it chilled."),{heading:"Where and when you can buy alcohol",body:["You must be 18 to buy alcohol, and shops and bars ask for ID from anyone who looks under 25. The accepted ID is a passport, a New Zealand driver licence or a Kiwi Access Card, so carry your passport: an overseas driver licence is often refused.","Shops can sell alcohol between 7am and 11pm at most, and many councils set shorter hours, often stopping at 9pm, so do not count on a late run to the bottle store. Shops cannot sell alcohol on Good Friday, Easter Sunday or Christmas Day, or before 1pm on Anzac Day, and bars can then serve only people having a meal. Many towns also have alcohol-free zones in streets, parks and beaches, especially over summer and New Year, with a fine of about $250 for drinking there.","Craft beer is well established, and most regions have a local brewery worth a stop, many with a taproom and food. If you are crossing the Tasman as well, the AussieCamps guide to beer prices in Australia covers pubs and bottle shops there."]}],sources:[numbeo,rbnz]}),
  a({slug:"accommodation-costs-new-zealand-2026",title:"NZ Accommodation Costs 2026: Hostels, Cabins and Hotels",description:"What dorm beds, holiday park cabins and private rooms cost in New Zealand in 2026, and what each price band includes, so you can budget each night.",category:"Costs & budget",region:"New Zealand",places:["Hostels","Holiday park cabins","Motels","Hotels","Backcountry huts"],imageAlt:"New Zealand accommodation overlooking mountains",intro:"In New Zealand a hostel dorm bed costs about NZ$30 to $75 a night, a holiday park cabin $85 to $155, a budget private room $110 to $220 and a mid-range hotel room $180 to $400, and Queenstown, school holidays and event nights can go higher. Price depends on the date and destination more than the national label: a shared-bathroom cabin can beat a hostel private room, while a remote mountain location can exceed a city hotel.",priceTable:table("Indicative planning bands assembled from live 2026 directory examples and operator guides. Search exact dates for a real quote.",[{label:"Hostel dorm bed",nzdLow:30,nzdHigh:75,unit:"per person per night"},{label:"Holiday park cabin",nzdLow:85,nzdHigh:155,unit:"per room per night"},{label:"Budget private room",nzdLow:110,nzdHigh:220,unit:"per room per night"},{label:"Mid-range hotel",nzdLow:180,nzdHigh:400,unit:"per room per night"}]),sections:[s("Read what is private","A private bedroom may still use a shared bathroom or kitchen, while a motel unit often includes cooking facilities. Linen, towels and cleaning can also differ.","Compare the final checkout amount for the same guest count. Base rates can add extra people or card fees."),s("Dates dominate averages","Queenstown, Aoraki, school holidays and event nights can exceed the range. Midweek and shoulder-season stays may fall below it.","Book hard locations early, but read cancellation terms when weather could change the route."),s("Use rooms strategically","A roofed night after heavy rain can dry gear, protect sleep and make the next camp possible. It need not replace the whole camping plan.","Choose location with parking and onward travel in mind. A cheap central room can become difficult with a tall vehicle." ),s("What each accommodation type is actually for","A hostel dorm is the cheapest bed and buys you a kitchen and other travellers. A holiday park cabin costs more than a site but less than a motel and solves a wet night. A motel unit is the standard New Zealand middle option and usually includes a kitchenette, which lowers the food cost of staying in one.","Backpacker private rooms sit between dorms and motels and are frequently the best value for a couple. Hotels are largely a city product here and rarely the right answer on a touring route.",["Motels usually include a kitchenette","Backpacker doubles beat motels for couples","Cabins solve a wet night cheaply"]),s("When paying for a room is the right call","After several nights of rain, before a very early ferry, when someone is unwell, or when the forecast makes a tent genuinely unsafe. In each of those cases the room is not a luxury, it is the thing that keeps the trip going, and budgeting for a few of them in advance removes the argument.","A room also resets everything at once: laundry, hot water, charging, drying, a proper night's sleep. Counted against the jobs it replaces, it is frequently better value than the nightly rate suggests."),s("Booking windows and cancellation","Between Christmas and late January, and around Easter and long weekends, popular towns book out weeks ahead and impose minimum stays. Outside those windows most places have availability a few days out, which is what makes shoulder-season travel so much easier.","Where your dates are uncertain, pay for refundable terms and write the cancellation deadline into the trip stop. The difference in price is usually small and the flexibility is worth more than the saving on a route that depends on weather.",["Book peak dates weeks ahead","Shoulder season needs days, not weeks","Note cancellation deadlines"]),s("Reading the total, not the rate","Compare the final amount for your actual party and nights, including linen, parking, booking fees and whether breakfast is included. A per-person rate and a per-room rate look similar and are not, and the gap widens with every extra person.","Check the location as well as the price. A cheaper place twenty minutes out of town costs fuel twice and removes the option of walking to dinner, which is often the reason you wanted the room in the first place."),{heading:"Membership schemes and discounts",body:["Holiday park chains and motoring associations run membership schemes that discount nightly rates, and on a trip of more than a week or two the membership frequently pays for itself. Check whether your home motoring association has a reciprocal arrangement before paying for a new one.","Booking direct with a holiday park is often cheaper than through a booking platform, and it gives you a person to talk to about late arrival or a site that fits your vehicle. Platforms are useful for comparing and less useful for arranging.","Longer stays attract weekly rates at many parks, sometimes a substantial discount. If you are basing yourself somewhere for four nights or more, ask rather than booking night by night. Heading to Australia too? The AussieCamps guide to accommodation costs in Australia compares the same options there."]}],sources:[{label:"Hostelworld New Zealand listings",url:"https://www.hostelworld.com/hostels/oceania/new-zealand/"},rbnz]}),
  a({slug:"new-zealand-road-trip-fuel-cost-2026", related: ["road-user-charges-campervan-new-zealand"],title:"NZ Petrol Prices 2026 and Campervan Fuel Cost",description:"Average NZ 91 petrol price by month in 2026 from MBIE, and what 500 to 3,000 km costs in a campervan at 9 to 12 L/100 km, plus diesel road user charges.",category:"Costs & budget",region:"New Zealand roads",places:["Auckland","Wellington","Christchurch","West Coast","Fiordland"],imageAlt:"Campervan refuelling during a New Zealand road trip",intro:"Fuel turns itinerary design into a measurable cost. In the week dated 9 October 2026, MBIE's national average board price for regular 91 petrol was $3.54 a litre and diesel $3.24, after a year that swung from $2.56 in February to $3.44 in April.",priceTable:{...table("The petrol benchmark is MBIE's national average board price for regular 91 in the week dated 9 October 2026 (provisional). Route examples are mechanical calculations before remote price variation.",[{label:"Regular 91 petrol",nzdLow:3.54,unit:"per litre"},{label:"500 km at 9 L/100 km",nzdLow:159.3,unit:"45 litres"},{label:"1,000 km at 11 L/100 km",nzdLow:389.4,unit:"110 litres"},{label:"3,000 km at 12 L/100 km",nzdLow:1274.4,unit:"360 litres"}]),asOf:"2026-10-20"},sections:[s("Calculate the actual vehicle","Multiply kilometres by litres per 100 kilometres, divide by 100, then multiply by the price per litre. Use the loaded campervan's likely consumption, not a small-car average.","Add detours and local driving. A 2,000-kilometre route can produce several hundred extra kilometres through camps, shops and viewpoints."),s("Allow for geography","Remote stations and tourist corridors can charge more than the national benchmark. Fill before long gaps and do not pass dependable fuel for a minor expected saving.","Headwind, mountain roads, roof equipment and load increase consumption. Update the estimate after the first two tanks."),s("Treat volatility honestly","Stats NZ reported petrol up 24.3 percent and diesel up 55.8 percent in the year to September 2026. MBIE's monthly averages for regular 91 ran $2.59 in January, $2.56 in February, $3.00 in March, $3.44 in April, $3.27 in May, $3.16 in June, $2.98 in July, $3.03 in August and $3.16 in September, so a figure from a few months ago can understate the route by 50 cents a litre.","Use the fuel calculator with today's board price and keep a margin for the remote leg." ),s("Petrol, diesel and road user charges","Diesel has been cheaper per litre than 91 for most of 2026, about 30 cents less in October, though it cost more for six weeks in April and May. Diesel vehicles also pay road user charges separately, bought in advance per thousand kilometres. If you are hiring, check whether RUC is included in the daily rate or billed at the end, because it materially changes the comparison with petrol.","For a private vehicle, RUC must be current for the distance you drive and is enforced. Buying it is straightforward online or at a licensing agent, and running past your purchased distance carries a penalty.",["Diesel pays RUC on top of fuel","Ask whether hire rates include RUC","Keep RUC ahead of your odometer"]),s("Where fuel costs most","Prices are lowest in the main centres and around competitive suburban sites, and highest on remote stretches with a single operator. The West Coast, Fiordland, the East Cape, inland Otago and the far north all carry a premium, sometimes a large one.","That premium is not a reason to run the tank low. The cost of filling twenty litres at a higher price is trivial compared with running out somewhere with no reception, and the stations that charge most are usually the ones with no competitor for a hundred kilometres."),s("What actually changes consumption","Load, roof boxes, headwind, sustained hill climbing and speed all matter, and a loaded campervan into a Canterbury nor'wester can use a quarter more than the brochure figure. Air conditioning has a small effect; idling the engine to run heating has a larger one than most people assume.","Tyre pressures matter and should be set for the loaded vehicle, not the empty one. Rental campervans frequently arrive underinflated, which costs fuel and handling at the same time.",["Set pressures for the loaded vehicle","Headwind costs more than aircon","Roof boxes are expensive at speed"]),s("Reduce the bill without cutting the trip","The largest saving available is fewer unnecessary kilometres. Grouping nearby stops, avoiding a backtrack and accepting that you cannot see both islands properly in ten days will save more than any amount of careful driving technique.","After that, steady speeds and early braking help modestly. What does not help is coasting in neutral, which costs you engine braking and control on descents, or carrying fuel in unsuitable containers."),{heading:"Loyalty schemes and where to fill",body:["The main fuel retailers run discount schemes linked to supermarket spending, and the vouchers stack with some card offers. On a long trip these produce a real saving, though never enough to justify driving past the last station before a remote leg.","Unstaffed automated stations are common in small towns and are usually cheaper, but some reject foreign cards. Have a backup card and do not arrive at one with an empty tank late at night expecting it to work.","Prices vary noticeably between towns even within a region. In the main centres it is worth filling before heading out rather than at the last suburban station, which is frequently the most expensive one on the route. Road-tripping across the Tasman too? The AussieCamps guide to fuel costs in Australia works out the same sums there."]}],sources:[{label:"MBIE weekly fuel price monitoring",url:"https://www.mbie.govt.nz/building-and-energy/energy-and-natural-resources/energy-statistics-and-modelling/energy-statistics/weekly-fuel-price-monitoring"},{label:"Stats NZ: selected price indexes, September 2026",url:"https://www.stats.govt.nz/information-releases/selected-price-indexes-september-2026/"},rbnz]}),
  a({slug:"public-transport-costs-new-zealand-2026",title:"NZ Public Transport Costs 2026: Auckland Fares and Caps",description:"Auckland bus, train and ferry fares in 2026: $3 for one zone, a $50 seven-day cap on AT HOP, and typical one-way fares in other NZ towns.",category:"Costs & budget",region:"Auckland and Wellington",places:["Auckland Transport","AT HOP","Metlink","Contactless payment"],imageAlt:"Public transport in a New Zealand city",intro:"An adult bus or train fare in Auckland costs NZ$3 for one zone and $7.90 for four or more on AT HOP, the CityLink bus is $0.95, and AT HOP travel is capped at $50 over seven days. City fares use local cards, zones, contactless rules and exclusions, so compare the actual day or week of travel rather than one ticket from each network.",priceTable:{...table("Auckland adult fares current from 1 February 2026. National one-way range is the June 2026 community benchmark.",[{label:"Auckland CityLink",nzdLow:.95,unit:"AT HOP or contactless"},{label:"Auckland 1 zone",nzdLow:3,unit:"adult"},{label:"Auckland 2 zones",nzdLow:4.9,unit:"adult"},{label:"Auckland 4+ zones",nzdLow:7.9,unit:"adult"},{label:"Auckland 7-day cap",nzdLow:50,unit:"AT HOP eligible services"},{label:"Typical local one-way",nzdLow:2.5,nzdHigh:6,unit:"national community range"}]),asOf:"2026-11-03"},sections:[s("Payment changes the outcome","Auckland's $50 seven-day cap applies to eligible AT HOP travel, while contactless payment has a $20 daily cap. Not every ferry is included.","Tag on and off correctly. A missed tag can change the charge or prevent travel counting toward a cap."),s("Networks are local","Metlink uses its own zones, fares and transfer rules, with changes effective 15 May 2026. Other cities use separate cards or contactless systems.","Check airport buses, ferries and tourist services individually because flat or premium fares often sit outside ordinary caps."),s("Leave the campervan parked","Public transport can remove central parking, height-limit and alcohol-driving problems. Add the campsite-to-stop connection when comparing cost.","For two or more people, a single fare still needs multiplying by every traveller and both directions." ),s("Cards, contactless and the regional patchwork","New Zealand has no single national transport card. Auckland uses AT HOP, Wellington uses Snapper, and other regions run their own systems, with contactless bank card payment rolling out unevenly. A card bought in one city may be useless in the next.","For a short visit, check whether the city you are in accepts contactless before buying a stored-value card. For a longer stay in Auckland or Wellington, the card usually pays for itself quickly through cheaper fares than cash.",["No national transport card","Check contactless before buying a card","Cash fares are the most expensive"]),s("Airport connections","Auckland, Wellington and Christchurch all have bus links to the city, priced separately from ordinary urban fares and considerably cheaper than a taxi or rideshare. Queenstown's airport bus is short and inexpensive. None of these are included in a standard day pass.","Price the airport leg on its own when comparing options, and factor in luggage. With three or more people and bags, a rideshare is sometimes competitive with individual bus fares, which is rarely true for one traveller."),s("When public transport beats the campervan","Driving a large vehicle into central Auckland or Wellington is unpleasant and parking is expensive and height-restricted. Leaving the van at a campground or park-and-ride and taking the bus or train in is usually faster, cheaper and much less stressful.","The same logic applies in Queenstown in peak season, where parking a campervan near the centre is genuinely difficult. Base yourself outside and use the local service for the days you want to be in town.",["Height limits catch campervans out","Park and ride into Auckland and Wellington","Queenstown parking is hard in season"]),s("Where there is no service at all","Most of rural New Zealand has no meaningful public transport, and what exists is often a single school-linked service. A trip planned around buses works between the main centres and tourist hubs and does not work for reaching most campsites, trailheads or small towns.","If you are travelling without a vehicle, plan around the intercity coach network and the tourist shuttles serving specific tracks, and accept that the itinerary is shaped by those routes rather than by where you would ideally go."),{heading:"Getting around without a car in the cities",body:["Auckland's rail and bus network covers the isthmus reasonably and the ferry to Devonport and Waiheke is worth taking for its own sake. Wellington is compact enough to walk, with the cable car and a suburban rail network for anything further out.","Christchurch runs a bus network from a central exchange and is flat enough that cycling is genuinely practical, with an expanding network of separated cycleways. Bike hire is widely available and often better value than a day of bus fares.","Concessions exist for children and older travellers, and some cities offer day passes that beat individual fares once you make three or four trips. Work out the expected number of trips before choosing between a pass and paying per journey. Heading to Australia as well? The AussieCamps guide to public transport costs in Australia covers the fares there."]}],sources:[{label:"Auckland Transport 2026 fares",url:"https://at.govt.nz/bus-train-ferry/fares-and-discounts/public-transport-fare-changes"},{label:"Auckland seven-day fare cap",url:"https://at.govt.nz/7dayfarecap"},{label:"Metlink fares",url:"https://www.metlink.org.nz/getting-started/tickets-and-fares"},rbnz]}),
  a({slug:"domestic-flight-costs-new-zealand-2026",title:"Domestic Flight Costs in NZ 2026: The Real Trip Price",description:"What a domestic flight in New Zealand really costs once baggage, airport transport and the rental car or campervan you leave behind are added.",category:"Costs & budget",region:"New Zealand airports",places:["Auckland","Wellington","Christchurch","Queenstown","Regional airports"],imageAlt:"Domestic aircraft flying over New Zealand",intro:"Domestic fares change too quickly for a permanent national price table to be honest. Use scenario bands to budget, then compare the full airline checkout for the exact date.",priceTable:table("Planning bands rather than standing quotes. Route, booking lead time, luggage and disruption flexibility dominate the total.",[{label:"Short trunk-route sale",nzdLow:69,nzdHigh:149,unit:"one way before extras"},{label:"Typical trunk route",nzdLow:120,nzdHigh:300,unit:"one way"},{label:"Regional or peak route",nzdLow:200,nzdHigh:550,unit:"one way"},{label:"Checked baggage allowance",nzdLow:25,nzdHigh:80,unit:"planning add-on range"}]),sections:[s("Compare the fare family","Air New Zealand domestic products include different baggage and change flexibility. A low seat fare can lose its advantage when camping equipment requires a bag.","Read dangerous-goods rules for fuel bottles, gas canisters, batteries and outdoor equipment before reaching security."),s("Add both airports","Include transport, parking, rental change and the time needed for check-in. A flight can save a day across the country but rarely replaces only the driving fuel.","One-way vehicle fees or an unused rental day can outweigh the ticket."),s("Search, then record","Use the table only as a reserve for early planning. Once dates are known, save the exact total and fare conditions from the airline.","Keep weather and connection margin, particularly for a regional flight before an international departure." ),s("The routes worth flying","Flying earns its place on the long diagonals: Auckland to Queenstown, Auckland to Christchurch, or anything involving Stewart Island or the Chathams. On those the time saved is a full day or more, which on a two-week trip is a substantial fraction of the holiday.","It rarely makes sense for shorter hops that a scenic drive covers well, and it never makes sense if it means paying for a vehicle sitting idle at the other end. Price the whole arrangement, not the fare.",["Fly the long diagonals","Do not fly past scenery you came for","Count the idle vehicle days"]),s("Baggage is where the cheap fare goes","The lowest advertised fares are typically seat-only, and adding checked baggage, seat selection and any change flexibility can double the price. For campers with packs, a tent and cooking gear, checked baggage is not optional.","Weight limits are enforced on smaller regional aircraft, and some routes have tighter allowances than the main trunk services. Check the specific aircraft rather than assuming a single airline standard."),s("Weather and regional reliability","Queenstown, Wellington, Milford and several regional airports are weather-affected more often than visitors expect. Queenstown in particular has terrain-driven approach restrictions, and Wellington is genuinely windy. Cancellations and diversions are a normal part of flying here.","Do not schedule a domestic flight to connect tightly with an international departure on the same day. A night in the departure city is far cheaper than a missed long-haul flight.",["Never connect tightly to international","Queenstown and Wellington divert often","Build a buffer night before flying home"]),s("One-way vehicle logistics","Flying one leg usually means a one-way rental, and the relocation fee for that can be larger than the airfare. Some operators waive it in the low season or on routes where they need vehicles moved, which is worth asking about directly.","Relocation deals, where you move a vehicle for the company at a nominal daily rate, are a genuine option if your dates and direction happen to match. They come with tight time limits, so they suit a direct transit rather than a leisurely trip."),{heading:"Booking windows and sale fares",body:["Domestic fares are cheapest booked several weeks ahead and rise sharply in the final fortnight. Sales appear regularly and are worth waiting for on a flexible route, though the cheapest fares carry no flexibility at all.","School holidays, Easter and the period around Christmas see both higher fares and full aircraft, and regional routes with a single daily service sell out early. If your dates fall in those windows, book as soon as they are fixed.","Carry-on-only fares are competitive with a coach ticket on some routes if you are travelling light, which occasionally makes flying the cheaper option as well as the faster one. That calculation changes entirely once camping gear is involved. Flying on to Australia? The AussieCamps guide to domestic flight costs in Australia covers the fares there."]}],sources:[{label:"Air New Zealand domestic fares",url:"https://www.airnewzealand.com/en-nz/domestic-fares"},rbnz]}),
  a({slug:"bus-ferry-train-costs-new-zealand",title:"Bus, Ferry and Train Costs in New Zealand (2026)",description:"Intercity coach, Cook Strait ferry and scenic rail in New Zealand compared: what each journey suits and why each needs its own quote.",category:"Costs & budget",region:"New Zealand intercity travel",places:["InterCity","Cook Strait ferry","Northern Explorer","Coastal Pacific","TranzAlpine"],imageAlt:"Scenic train travelling through New Zealand",intro:"Long-distance public transport is a mix of practical coaches, vehicle ferries and tourism-focused rail. Price, schedule, luggage and the transport replaced should be compared together.",priceTable:table("Planning bands based on 2026 products; operators use dynamic dates and limited sale inventory. Quote the exact journey before committing.",[{label:"Intercity coach",nzdLow:20,nzdHigh:120,unit:"typical one-way planning band"},{label:"Cook Strait foot passenger",nzdLow:75,nzdHigh:130,unit:"one way planning band"},{label:"Cook Strait car or camper",nzdLow:220,nzdHigh:650,unit:"vehicle and travellers"},{label:"Scenic rail",nzdLow:180,nzdHigh:400,unit:"one way planning band"}]),sections:[s("Coach fares trade flexibility","InterCity standard and Flexi products use different change and refund terms, while low GoTickets have limited availability. Compare luggage and amendment fees with the fare.","A coach reaches many towns but may not connect directly to a campground or trailhead."),s("The ferry prices the vehicle","Cook Strait vehicle cost changes with dimensions and passengers. Enter racks, trailers and campervan height accurately, then read change conditions.","Foot travel is cheaper but requires a plan for gear and transport at both terminals."),s("Scenic rail is an experience","Northern Explorer, Coastal Pacific and TranzAlpine services are not substitutes for an ordinary commuter train. Their schedule and fare include the value of the journey itself.","Price the onward night because arrival time can remove a same-day connection. A cheap seat with an extra hotel may not be the lower total." ),s("The intercity coach network","Long-distance coaches connect the main centres and most tourist towns, and booked well ahead they are the cheapest way to move between cities without a vehicle. Fares rise steeply close to departure, so the flexibility of booking late is expensive.","Coaches are slower than driving and stop frequently, which is fine if you treat the journey as part of the day. What they do not do is get you to trailheads, DOC campsites or anywhere off the main highway.",["Book coaches early for the low fares","Coaches serve towns, not trailheads","Slower than driving, by design"]),s("The three scenic rail journeys","New Zealand's passenger rail is a tourism product rather than transport: the TranzAlpine between Christchurch and Greymouth, the Coastal Pacific up to Picton, and the Northern Explorer between Auckland and Wellington. They are priced accordingly and run limited timetables, often seasonally.","The TranzAlpine in particular is worth doing for its own sake, and it works well as a return day trip from Christchurch. Treat all three as experiences you are buying rather than a way to save money on a transfer."),s("Cook Strait as the fixed cost","The Interislander and Bluebridge crossings are the only way to take a vehicle between the islands, and they are a significant, non-negotiable line in any two-island budget. Foot passenger fares are far cheaper, which occasionally makes a vehicle swap on either side worth pricing.","Book summer sailings well ahead, and read the change conditions before choosing a cheap fare. Weather cancellations are routine on this crossing, and an inflexible ticket is a false economy.",["Foot passengers pay far less","Book summer sailings ahead","Weather cancellations are routine"]),s("Smaller ferries you may need","Stewart Island is reached by ferry from Bluff or by air from Invercargill, and the crossing is short but frequently rough. Waiheke and the inner Hauraki Gulf islands run regular Auckland services, and there are vehicle ferries for some of them at a much higher price than the passenger fare.","Water taxis serve Abel Tasman, the Marlborough Sounds and parts of Fiordland, and for those they are not a luxury but the practical way in and out. Budget them as part of the walk rather than as an extra."),{heading:"Passes and hop-on hop-off networks",body:["Several operators sell flexible passes covering a set number of trips or a period of travel, aimed at backpackers moving between hostels and towns. These work well if your route matches the network and poorly if you want to stop anywhere it does not serve.","Compare the pass against the sum of the individual fares you would actually book, not the maximum possible use. Most people use fewer trips than they expected when they bought it.","Booking individual coach tickets early is frequently cheaper than any pass, particularly outside peak season. The pass buys flexibility rather than a lower price, so decide which of the two you actually need. Heading to Australia as well? The AussieCamps guide to bus and train costs in Australia covers long-distance travel there."]}],sources:[{label:"InterCity fare types",url:"https://www.intercity.co.nz/travel-info/standard-vs-flexi-fares"},{label:"Great Journeys New Zealand",url:"https://www.greatjourneysnz.com/"},rbnz]}),
];
